-- CA_0218_la_community_college_boards_batch1.sql
-- CA_0218: LA County community college boards -- Los Angeles Community College District, Santa Monica Community College District.
--
-- MODEL (new: the DB had NO community-college rows at all -- no government, chamber, district, polygon or office):
--   per college district: one government ("<District>, California, US", LOCAL) + one chamber "Board of Trustees";
--   by-trustee-area boards: one SCHOOL district + one X0002 polygon per area (geo_id '<slug>-ta-N'), one office each;
--   at-large boards: one SCHOOL district + one X0002 polygon for the whole college district, one office per seat.
--   X0002 is the layer both GEOFENCE_DISTRICT_JOIN and MTFCC_DISTRICT_TYPE_GUARD admit for SCHOOL.
-- POLYGONS: LA RR/CC master precinct layer (public.gis.lacounty.gov/.../Political_Boundaries/MapServer/34, 33,236
--   precincts) dissolved by DST_JRC (college district) / DIV_JRC (trustee area). DIV_JRC = the trustee-area number:
--   checked against the colleges' own area descriptions for Compton, Rio Hondo, Long Beach, Pasadena and Citrus
--   (every area's communities match). Slivers < 100 m2 dropped, simplified at 2e-6 deg, make_valid. Local QA: each
--   district's areas union to its whole-district dissolve (ratio 1.00000), max pair overlap < 1.1e-8 deg2, and no two
--   college districts overlap.
-- TRUSTEES: each college's own board page (read 2026-09-23), cross-checked with RR/CC candidate lists + results for
--   Nov 2022 (id 4300), Nov 2024 (4324), Jun 2022 (4269), Mar 2024 (4316). Term start: Nov-election winners
--   YYYY-12-01 'month' 'elected' (house convention); primary-cycle PCC: sourced month or 'year'; appointees: the
--   appointment date 'day' 'appointed'. Party is never stored.
-- CANDIDATES: RR/CC Nov 3 2026 list (lavote.gov/Apps/CandidateList/Index?id=4348); only names whose nomination
--   papers were FILED (arg[8]) -- papers-only names are excluded. Uncontested seats are seeded too (operator
--   decision 2026-09-22). Incumbents (RR/CC flag E/A) are linked to the seated trustee; challengers unlinked.
-- RACES go on '2026 LA County General' (d91a20ce-557e-4615-a31b-5b2b3df2ed14); primary_party NULL.
-- Apply with: npx tsx scripts/_apply-file.ts <abs path>   (geometry-heavy; do not paste through MCP).
--
-- Los Angeles Community College District (at large, 7 seats; RR/CC DST_JRC 45; https://www.laccd.edu/board):
--   Seat 1: Andra Hoffman -- elected 2024-12-01 (month) [reused row 9234e0a1]
--   Seat 2: Steven F. Veres -- elected 2022-12-01 (month)
--   Seat 3: David Vela -- elected 2024-12-01 (month) [reused row dc464ba5]
--   Seat 4: Sara Hernandez -- elected 2022-12-01 (month) [reused row 3ce8b7fa]
--   Seat 5: Nichelle Henderson -- elected 2024-12-01 (month) [reused row b133671a]
--   Seat 6: Gabriel Buelna -- elected 2022-12-01 (month)
--   Seat 7: Kelsey K. Iino -- elected 2024-12-01 (month) [reused row ed690014]
-- Santa Monica Community College District (at large, 7 seats; RR/CC DST_JRC 34; https://admin.smc.edu/administration/governance/board-of-trustees/index.php):
--   Seat 1: Sion Roy -- elected 2022-12-01 (month)
--   Seat 2: Tom Peters -- elected 2022-12-01 (month)
--   Seat 3: Nancy Greenstein -- elected 2022-12-01 (month)
--   Seat 4: Luis Barrera Castañón -- appointed 2025-02-04 (day)
--   Seat 5: Margaret Quiñones-Perez -- elected 2024-12-01 (month)
--   Seat 6: Rob Rader -- elected 2024-12-01 (month)
--   Seat 7: Anastasia Foster -- elected 2024-12-01 (month)
--
-- BATCH NOTES:
--   LACCD: 7 at-large seats, numbered; the 2026 ballot has Seats 2, 4, 6 (board page: "In 2026, elections will be held
--     for Board Seats 2, 4 and 6"). Seat 4 is OPEN: Sara Hernandez is not on the list (her row -- reused -- is the 2026
--     State Senate District 26 candidate row). Nichelle Henderson's reused row is her 2026 Superintendent candidacy.
--     Hoffman / Vela / Iino rows were 2024 NetFile filers for these same seats (source netfile_laco_2024).
--   SANTA MONICA CCD: 7 at-large, unnumbered seats; 4 on the 2026 ballot (LACOE Bulletin 7112). Its candidates file
--     with the SANTA MONICA CITY CLERK, so they are NOT on RR/CC list 4348: 5 candidates for 4 seats from
--     santamonica.gov/elections/2026-11-02/general-election-2026 (ballot designations kept). The seats up are the 2022
--     cohort (Roy, Greenstein, Peters, and Barry Snell's -- Snell left on election to the SM City Council, Dec 2024;
--     Luis Barrera Castanon appointed Feb 4 2025). Nancy Greenstein does not run, so the 4-seat race binds to her office.
--     2024 cohort (not up): Quinones-Perez, Rader, Foster.
--   Student trustees are not modeled (advisory vote only).
BEGIN;

-- ─── 1. Government + governing board (chamber) per college district (none existed) ─────────
INSERT INTO essentials.governments (id, name, type, state)
SELECT v.id, v.name, 'LOCAL', 'CA'
  FROM (VALUES
    ('c5c11d00-ba13-5910-bde1-e0eff4e694f0'::uuid, 'Los Angeles Community College District, California, US'),
    ('4125d303-75e1-5a62-b508-93c73471c682'::uuid, 'Santa Monica Community College District, California, US')
  ) AS v(id, name)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.governments g WHERE g.id = v.id);

INSERT INTO essentials.chambers (id, government_id, name, name_formal, term_length, election_frequency, website_url, policy_engagement_level)
SELECT v.id, v.gid, 'Board of Trustees', v.name_formal, '4 years', '4 years', v.url, 'full'   -- slug is generated
  FROM (VALUES
    ('8e8e0830-ca80-505e-a8cb-279469468f73'::uuid, 'c5c11d00-ba13-5910-bde1-e0eff4e694f0'::uuid, 'Los Angeles Community College District Board of Trustees', 'https://www.laccd.edu/board'),
    ('d4db51ae-49eb-5118-b4cb-7a6537d9dd56'::uuid, '4125d303-75e1-5a62-b508-93c73471c682'::uuid, 'Santa Monica Community College District Board of Trustees', 'https://admin.smc.edu/administration/governance/board-of-trustees/index.php')
  ) AS v(id, gid, name_formal, url)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.chambers c WHERE c.id = v.id);

-- ─── 2. Polygons (RR/CC precinct layer dissolved by DST_JRC / DIV_JRC; DIV = trustee-area number) ─
