-- ─── 8. Post-verify gate ──────────────────────────────────────────────────────────────────
DO $$
DECLARE n int; n2 int;
BEGIN
  SELECT count(*) INTO n FROM essentials.geofence_boundaries gb
   WHERE gb.mtfcc = 'X0002' AND gb.geo_id IN (SELECT d.geo_id FROM essentials.districts d WHERE d.government_id IN ('c5c11d00-ba13-5910-bde1-e0eff4e694f0'::uuid, '4125d303-75e1-5a62-b508-93c73471c682'::uuid))
     AND public.ST_IsValid(gb.geometry) AND NOT public.ST_IsEmpty(gb.geometry);
  IF n <> 2 THEN RAISE EXCEPTION 'expected 2 valid polygons, got %', n; END IF;

  SELECT count(*) INTO n FROM essentials.districts d WHERE d.government_id IN ('c5c11d00-ba13-5910-bde1-e0eff4e694f0'::uuid, '4125d303-75e1-5a62-b508-93c73471c682'::uuid) AND d.district_type = 'SCHOOL' AND d.mtfcc = 'X0002';
  IF n <> 2 THEN RAISE EXCEPTION 'expected 2 SCHOOL districts, got %', n; END IF;

  -- every seat is held by exactly the trustee named for it (office_current_holder = query-time occupant)
  SELECT count(*) INTO n FROM (VALUES ('257c9462-8d1d-5168-aba0-9508dc3da238'::uuid, '9234e0a1-4a7e-4922-b43d-6cb31e7d58d4'::uuid), ('b688c906-9598-5d60-aced-f341d6b80cd7'::uuid, '6f2748c9-a88d-5fe9-b1b9-39bafe5bb777'::uuid), ('4bb792f3-93f3-50c0-a8c9-e299a64c40da'::uuid, 'dc464ba5-d6f4-4380-88d4-615e708dab26'::uuid), ('1ebb9cdc-fa59-562d-b0e7-7f8bc9e7a264'::uuid, '3ce8b7fa-a703-45be-9e07-71b1a8ebfa8d'::uuid), ('439bafb1-ac47-5df9-9496-393391f76769'::uuid, 'b133671a-6470-4c0f-9883-9e9485476afc'::uuid), ('952e9ec4-39cd-5e98-b248-5f4753010c4f'::uuid, '53bd4003-50ec-51dc-9552-1d0787890a1f'::uuid), ('11a53715-f8f2-5eb8-bb77-a8ecebc8ede9'::uuid, 'ed690014-1f55-4620-98d2-76b54ec16ac1'::uuid), ('b9ff2b66-6bd7-561d-bce6-c2f1011b7fbc'::uuid, '72c8ea7b-2719-5b99-a734-e27a2ff519da'::uuid), ('7e3c495c-e89f-5fab-be93-8168a52d402a'::uuid, '7f4aa6e9-cf11-59bd-b40d-9a3d8a6f4e3c'::uuid), ('e14ebd74-4cb2-5f6c-86a0-bbb97dc8c8eb'::uuid, 'c470bdc9-3576-5db4-87b9-f31c3375fb0c'::uuid), ('7b140259-d0ba-57b4-9b87-2ad2067ce94b'::uuid, '10caf7c1-7cd7-5790-8b69-6c68f178bf93'::uuid), ('ceca7dc7-e2fe-5eb5-ac61-fe79f6e0d5a4'::uuid, 'aa47ae4b-bbc4-5263-955c-726432286510'::uuid), ('0d4e16a1-0dbd-5ae9-8cc9-0592faceca10'::uuid, '64ba15b8-bd8c-5c64-af5f-69a9046bcf98'::uuid), ('c37cb29c-a8be-5d92-a357-8d72ff3a4b16'::uuid, '4d48ca48-8f2d-568e-9624-849daf5097f5'::uuid)) AS v(oid, pid)
    JOIN essentials.office_current_holder och ON och.office_id = v.oid AND och.politician_id = v.pid;
  IF n <> 14 THEN RAISE EXCEPTION 'expected 14 seats each held by its named trustee, got %', n; END IF;
  SELECT count(*) INTO n FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
   WHERE d.government_id IN ('c5c11d00-ba13-5910-bde1-e0eff4e694f0'::uuid, '4125d303-75e1-5a62-b508-93c73471c682'::uuid);
  IF n <> 14 THEN RAISE EXCEPTION 'expected 14 offices, got %', n; END IF;

  SELECT count(*) INTO n FROM (VALUES ('257c9462-8d1d-5168-aba0-9508dc3da238'::uuid, '9234e0a1-4a7e-4922-b43d-6cb31e7d58d4'::uuid), ('b688c906-9598-5d60-aced-f341d6b80cd7'::uuid, '6f2748c9-a88d-5fe9-b1b9-39bafe5bb777'::uuid), ('4bb792f3-93f3-50c0-a8c9-e299a64c40da'::uuid, 'dc464ba5-d6f4-4380-88d4-615e708dab26'::uuid), ('1ebb9cdc-fa59-562d-b0e7-7f8bc9e7a264'::uuid, '3ce8b7fa-a703-45be-9e07-71b1a8ebfa8d'::uuid), ('439bafb1-ac47-5df9-9496-393391f76769'::uuid, 'b133671a-6470-4c0f-9883-9e9485476afc'::uuid), ('952e9ec4-39cd-5e98-b248-5f4753010c4f'::uuid, '53bd4003-50ec-51dc-9552-1d0787890a1f'::uuid), ('11a53715-f8f2-5eb8-bb77-a8ecebc8ede9'::uuid, 'ed690014-1f55-4620-98d2-76b54ec16ac1'::uuid), ('b9ff2b66-6bd7-561d-bce6-c2f1011b7fbc'::uuid, '72c8ea7b-2719-5b99-a734-e27a2ff519da'::uuid), ('7e3c495c-e89f-5fab-be93-8168a52d402a'::uuid, '7f4aa6e9-cf11-59bd-b40d-9a3d8a6f4e3c'::uuid), ('e14ebd74-4cb2-5f6c-86a0-bbb97dc8c8eb'::uuid, 'c470bdc9-3576-5db4-87b9-f31c3375fb0c'::uuid), ('7b140259-d0ba-57b4-9b87-2ad2067ce94b'::uuid, '10caf7c1-7cd7-5790-8b69-6c68f178bf93'::uuid), ('ceca7dc7-e2fe-5eb5-ac61-fe79f6e0d5a4'::uuid, 'aa47ae4b-bbc4-5263-955c-726432286510'::uuid), ('0d4e16a1-0dbd-5ae9-8cc9-0592faceca10'::uuid, '64ba15b8-bd8c-5c64-af5f-69a9046bcf98'::uuid), ('c37cb29c-a8be-5d92-a357-8d72ff3a4b16'::uuid, '4d48ca48-8f2d-568e-9624-849daf5097f5'::uuid)) AS v(oid, pid) JOIN essentials.politicians p ON p.id = v.pid
   WHERE p.party IS NOT NULL OR NOT p.is_active OR NOT p.is_incumbent;
  IF n <> 0 THEN RAISE EXCEPTION '% seated trustee row(s) carry a party or are not active incumbents', n; END IF;

  -- partition: no two trustee areas of one district overlap beyond ~1,000 m2 (1e-7 deg2 at 34 N; planar, decision 0006)
  SELECT count(*) INTO n FROM essentials.districts a JOIN essentials.districts c ON c.government_id = a.government_id AND a.geo_id < c.geo_id
    JOIN essentials.geofence_boundaries ga ON ga.geo_id = a.geo_id AND ga.mtfcc = 'X0002'
    JOIN essentials.geofence_boundaries gc ON gc.geo_id = c.geo_id AND gc.mtfcc = 'X0002'
   WHERE a.government_id IN ('c5c11d00-ba13-5910-bde1-e0eff4e694f0'::uuid, '4125d303-75e1-5a62-b508-93c73471c682'::uuid) AND public.ST_Area(public.ST_Intersection(ga.geometry, gc.geometry)) > 1e-7;
  IF n <> 0 THEN RAISE EXCEPTION '% trustee-area pair(s) overlap', n; END IF;

  -- END TO END: an interior point of each polygon resolves (geofence -> X0002 SCHOOL district -> office -> holder)
  -- to exactly that district's own trustee(s) among this board's seats
  SELECT count(*) INTO n FROM essentials.districts me
    JOIN essentials.geofence_boundaries mg ON mg.geo_id = me.geo_id AND mg.mtfcc = 'X0002'
   WHERE me.government_id IN ('c5c11d00-ba13-5910-bde1-e0eff4e694f0'::uuid, '4125d303-75e1-5a62-b508-93c73471c682'::uuid)
     AND (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.geofence_boundaries gb
            JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.district_type = 'SCHOOL' AND d.mtfcc = gb.mtfcc
            JOIN essentials.offices o ON o.district_id = d.id
            JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id IS NOT NULL
           WHERE d.government_id = me.government_id AND gb.mtfcc = 'X0002'
             AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(mg.geometry)))
         IS DISTINCT FROM
         (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.offices o JOIN essentials.office_current_holder och ON och.office_id = o.id
           WHERE o.district_id = me.id);
  IF n <> 0 THEN RAISE EXCEPTION '% polygon(s) do not return exactly their own trustee(s) at an interior point', n; END IF;

  SELECT count(*), count(*) FILTER (WHERE r.office_id IS NULL OR r.primary_party IS NOT NULL) INTO n, n2
    FROM essentials.races r JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('c5c11d00-ba13-5910-bde1-e0eff4e694f0'::uuid, '4125d303-75e1-5a62-b508-93c73471c682'::uuid);
  IF n <> 4 OR n2 <> 0 THEN RAISE EXCEPTION 'expected 4 office-bound nonpartisan races, got % (% bad)', n, n2; END IF;
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('c5c11d00-ba13-5910-bde1-e0eff4e694f0'::uuid, '4125d303-75e1-5a62-b508-93c73471c682'::uuid);
  IF n <> 21 THEN RAISE EXCEPTION 'expected 21 candidates, got %', n; END IF;

  -- every incumbent candidate is linked to a trustee seated on this board
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('c5c11d00-ba13-5910-bde1-e0eff4e694f0'::uuid, '4125d303-75e1-5a62-b508-93c73471c682'::uuid) AND rc.is_incumbent
     AND NOT EXISTS (SELECT 1 FROM essentials.offices o2 JOIN essentials.districts d2 ON d2.id = o2.district_id
                       JOIN essentials.office_current_holder och ON och.office_id = o2.id
                      WHERE d2.government_id = d.government_id AND och.politician_id = rc.politician_id);
  IF n <> 0 THEN RAISE EXCEPTION '% incumbent candidate(s) not linked to a seated trustee', n; END IF;

  RAISE NOTICE 'CA_0218 applied: 2 boards, 2 polygons, 14 seats, 4 races, 21 candidates';
END $$;

COMMIT;
